fn solve(n: i8, s: Vec<char>) -> i8 {
    // Coordinates start at (0, 0)
    let mut x = 0;
    let mut y = 0;

    // Last region we were in: 
    // None = on the border or haven't entered a region yet
    // Some(true) = Region A (x > y)
    // Some(false) = Region B (y > x)
    let mut last_region: Option<bool> = None;

    let mut transitions = 0;

    for &ch in &s {
        match ch {
            'U' => y += 1,
            'R' => x += 1,
            _ => {} // Since input is guaranteed, no need to handle invalid input
        }

        if x == y {
            // On the border
            // Do not change last_region, just stay "none"
            // Because time on border itself doesn't count as transitions,
            // and we want to remember last region before border
            continue;
        }

        // Determine current region: true if Region A (x>y), false if Region B (y>x)
        let current_region = x > y;

        // If this is the first region we entered (last_region is None),
        // this initial entry doesn't count as transition
        // Just record the region
        if last_region.is_none() {
            last_region = Some(current_region);
        } else {
            // If we are in a different region than last time, count a transition
            if last_region.unwrap() != current_region {
                transitions += 1;
                last_region = Some(current_region);
            }
            // else same region, no transition count, just continue
        }
    }

    transitions
}